const DATA=window.SOLUTION_DATA,$=(q,r=document)=>r.querySelector(q),$$=(q,r=document)=>[...r.querySelectorAll(q)];
const saved=(()=>{try{return JSON.parse(localStorage.getItem('milesight-multisite-v2')||'null')}catch{return null}})();
const state=Object.assign({page:'explore',scenario:'retail',module:'people',zone:0,automation:'close',deployTab:'architecture',gateway:'ug63',gatewayOpen:false,stores:93,enabled:['people','hvac','energy','facility'],quantities:{people:4,hvac:3,energy:5,facility:4,iaq:2,cold:4,gateway:1},prices:{},mappings:{},roi:{electricity:30000,hvacShare:40,energySaving:1200,maintenanceSaving:180,service:240,capex:2400,labor:0}},saved||{});
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const money=v=>new Intl.NumberFormat('en-US',{maximumFractionDigits:0}).format(Number(v)||0);
const scenario=()=>DATA.scenarios[state.scenario],mods=()=>scenario().modules.map(id=>({id,...DATA.modules[id]}));
function persist(){try{localStorage.setItem('milesight-multisite-v2',JSON.stringify(state))}catch{}}
function toast(t){let e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2200)}
function download(n,c,t){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([c],{type:t}));a.download=n;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function scenarioPicker(compact=true){return `<div class="scenario-picker ${compact?'compact':''}">${Object.entries(DATA.scenarios).map(([id,s])=>`<button class="scenario-card ${state.scenario===id?'selected':''}" data-scenario="${id}"><span class="scenario-icon">${s.icon}</span><span><small>SCENARIO ${id==='retail'?'A':id==='restaurant'?'B':'C'}</small><b>${s.label}</b>${compact?'':`<em>${s.strap}</em>`}</span><i>${state.scenario===id?'✓':'→'}</i></button>`).join('')}</div>`}
const sceneImages={retail:'assets/scenes/retail-store.png',restaurant:'assets/scenes/restaurant-cold-chain.png',fitness:'assets/scenes/fitness-center.png'};
function overviewVisual(){return `<div class="network-visual scene-hero"><img src="${sceneImages[state.scenario]}" alt="2.5D cutaway view of ${esc(scenario().label)}"><div class="scene-caption"><small>SELECTED BUSINESS FORMAT</small><b>${esc(scenario().label)}</b><span>${esc(scenario().strap)}</span></div></div>`}
function coverHtml(){return `<section class="cover"><div class="cover-copy"><div class="cover-kicker">MILESIGHT / MULTI-SITE OPERATIONS</div><div class="eyebrow">CENTRALIZED MONITORING & SMART CONTROL<br>ACROSS EVERY LOCATION</div><h1>Smart Multi-Site<br><span>Business Solutions.</span></h1><p>From retail stores and restaurants to cafés and fitness centers, connect sensing, control and connectivity in one scalable IoT architecture.</p><div class="cover-pill-row"><span>MONITOR</span><span>ALERT</span><span>CONTROL</span></div><button class="cover-start" data-start>Choose a scenario <span>→</span></button></div><div class="cover-visual"><div><span class="eyebrow">ONE OPERATING MODEL · MULTIPLE BUSINESS FORMATS</span><h2>Choose a business scenario to explore.</h2><p>One gateway connects all sensors and controllers.</p></div>${overviewVisual()}${scenarioPicker(true)}</div></section>`}
function productCard(id){let p=DATA.products[id],v=p.image?`<img src="${p.image}" alt="${esc(p.model)}">`:`<div class="product-placeholder"><b>${esc(p.model)}</b><small>Image to confirm</small></div>`;return `<a class="product-card" href="${p.url}" target="_blank" rel="noopener"><div class="product-visual">${v}</div><div><b>${esc(p.model)}</b><span>${esc(p.name)}</span><p>${esc(p.use)}</p></div><i>↗</i></a>`}
function floorScene(){
  const points={
    retail:{people:[51,78],hvac:[57,15],energy:[84,30],facility:[17,22]},
    restaurant:{hvac:[56,13],energy:[82,27],facility:[14,30],cold:[80,73]},
    fitness:{people:[49,58],hvac:[56,13],energy:[78,18],facility:[18,25],iaq:[44,34]}
  }[state.scenario];
  return `<div class="floor-scene"><img src="${sceneImages[state.scenario]}" alt="2.5D cutaway view of ${esc(scenario().label)}">${mods().map((m,i)=>{let pos=points[m.id],fresh=state.scenario==='restaurant'&&m.id==='cold';return `<button class="hotspot ${state.module===m.id?'active':''} ${fresh?'new-module':''}" style="left:${pos[0]}%;top:${pos[1]}%" data-module="${m.id}"><span>${fresh?m.icon:i+1}</span><b>${m.name}</b></button>`}).join('')}</div>`
}
function peopleDataGroup(title,items,kind){return `<section class="people-data-group ${kind}"><div class="people-data-title"><small>${title}</small></div>${items.map(x=>`<div class="people-data-row"><div><b>${esc(x.label)}</b><small>${esc(x.note)}</small></div><strong>${esc(x.value)}</strong></div>`).join('')}</section>`}
function peopleView(m,z){let primary=DATA.products[z.devices[0]],pin=z.pin||{x:50,y:20},sceneImage=z.image==='selected-scene'?sceneImages[state.scenario]:z.image;return `<section class="module-detail people-detail panel"><div class="section-head"><div><span class="eyebrow">OPERATIONAL QUESTION</span><h2>${m.question}</h2></div><span class="module-mark">${m.icon}</span></div><p class="lead">${m.promise}</p><div class="zone-tabs">${m.zones.map((x,i)=>`<button class="${state.zone===i?'selected':''}" data-zone="${i}">${x.name}</button>`).join('')}</div><div class="people-case-grid"><div class="people-scene-card"><img class="people-scene-image" src="${sceneImage}" alt="${esc(z.name)} ${esc(m.name)} reference scene"><span class="install-dot" style="left:${pin.x}%;top:${pin.y}%"></span><div class="install-device">${primary.image?`<img src="${primary.image}" alt="${esc(primary.model)}">`:''}<div><small>DEVICE POSITION</small><b>${esc(z.installLabel)}</b></div></div><a href="${z.source}" target="_blank" rel="noopener">${esc(z.sourceLabel)} ↗</a></div><div class="people-data-stack">${peopleDataGroup('RAW DATA',z.raw,'raw')}${peopleDataGroup('CALCULATED DATA',z.calculated,'calculated')}</div></div><div class="action-enabled people-action"><small>ACTION ENABLED</small><p>${esc(z.action)}</p></div><div class="product-strip people-products">${z.devices.map(productCard).join('')}</div></section>`}
function moduleView(){let m=DATA.modules[state.module],z=m.zones[state.zone]||m.zones[0];if(state.module==='people'||state.module==='hvac'||state.module==='energy'||state.module==='facility'||state.module==='cold'||state.module==='iaq')return peopleView(m,z);return `<section class="module-detail panel"><div class="section-head"><div><span class="eyebrow">OPERATIONAL QUESTION</span><h2>${m.question}</h2></div><span class="module-mark">${m.icon}</span></div><p class="lead">${m.promise}</p><div class="zone-tabs">${m.zones.map((x,i)=>`<button class="${state.zone===i?'selected':''}" data-zone="${i}">${x.name}</button>`).join('')}</div><div class="operational-view"><div><small>REFERENCE OPERATIONAL VIEW</small><strong>${z.metric}</strong><span>${z.unit}</span></div><p>${z.note}</p></div><div class="action-enabled"><small>ACTION ENABLED</small><p>${m.action}</p></div><div class="product-strip">${m.products.map(productCard).join('')}</div></section>`}
function explore(){if(!scenario().modules.includes(state.module)){state.module=scenario().modules[0];state.zone=0}if(state.zone>=DATA.modules[state.module].zones.length)state.zone=0;return `<div class="page-title"><div><span class="eyebrow">01 · SINGLE-SITE VISIBILITY</span><h1>What can one connected location do?</h1></div>${scenarioPicker()}</div><div class="explore-layout"><section class="panel scene-panel"><div class="section-head"><div><h2>${scenario().label}</h2><p>${scenario().description}</p></div><span class="status ok">CONNECTED</span></div>${floorScene()}<div class="module-rail">${mods().map(m=>{let fresh=state.scenario==='restaurant'&&m.id==='cold';return `<button class="${state.module===m.id?'selected':''} ${fresh?'new-module':''}" data-module="${m.id}"><span>${m.icon}</span>${m.name}</button>`}).join('')}</div></section>${moduleView()}</div>`}
function hqProfile(){
  const commonCodes=['024','067','089','012','041','052','058','071','076','083','094','100'];
  const profiles={
    retail:{plural:'retail stores',prefix:'Retail Store',basis:'per 100 visits',metrics:{energy:{title:'Energy intensity',unit:'kWh',values:[43.4,40.8,39.2,37.8,36.9,36.2,35.7,35.1,34.8,34.1,33.7,32.9],median:'36.8',insight:'Store 024 is 18% above the peer median.'},environment:{title:'Comfort policy compliance',unit:'%',values:[72,78,81,86,91,92,93,94,95,96,96,97],median:'93',insight:'Three stores require temperature-policy review.'},traffic:{title:'Entry conversion',unit:'%',values:[21.8,23.4,24.1,26.8,28.9,29.4,30.1,30.8,31.2,31.7,32.1,33.4],median:'30.0',insight:'Store 089 trails the chain conversion median.'}},exceptions:[{store:'024',severity:'critical',title:'HVAC running after close',meta:'54 min outside operating policy',action:'Verify schedule and controller state'},{store:'067',severity:'review',title:'Energy intensity above peer band',meta:'+18% per 100 visits',action:'Inspect HVAC and lighting sub-loads'},{store:'089',severity:'review',title:'Entry conversion below chain median',meta:'−9.4% against comparable stores',action:'Review storefront and staffing pattern'}]},
    restaurant:{plural:'restaurants',prefix:'Restaurant',basis:'per 100 covers',metrics:{energy:{title:'Energy intensity',unit:'kWh',values:[58.2,54.7,52.4,49.5,48.9,48.2,47.6,46.8,46.3,45.7,45.1,44.6],median:'48.0',insight:'Restaurant 024 is above the peer energy band.'},environment:{title:'Cold-chain policy compliance',unit:'%',values:[74,79,83,88,91,92,93,94,95,96,97,98],median:'93',insight:'Door events explain two temperature exceptions.'},traffic:{title:'Covers per labor hour',unit:'',values:[9.8,10.4,10.9,11.6,12.1,12.4,12.8,13.1,13.4,13.7,14.1,14.4],median:'12.6',insight:'Restaurant 089 is below the staffing-efficiency band.'}},exceptions:[{store:'024',severity:'critical',title:'Cold cabinet above policy',meta:'7.8°C · door open 11 min',action:'Inspect cabinet door and product exposure'},{store:'067',severity:'review',title:'Kitchen load above peer band',meta:'+22% per 100 covers',action:'Review cooking and extraction schedules'},{store:'089',severity:'review',title:'HVAC running after close',meta:'38 min outside operating policy',action:'Verify closing sequence'}]},
    fitness:{plural:'fitness centers',prefix:'Fitness Center',basis:'per 100 visits',metrics:{energy:{title:'Energy intensity',unit:'kWh',values:[51.1,48.8,46.9,44.7,43.8,43.1,42.6,42.2,41.8,41.2,40.7,40.1],median:'43.0',insight:'Fitness Center 024 is above the peer energy band.'},environment:{title:'IAQ policy compliance',unit:'%',values:[71,77,82,87,90,92,93,94,95,96,97,98],median:'93',insight:'Peak occupancy drives the leading CO₂ exceptions.'},traffic:{title:'Visits per staffed hour',unit:'',values:[11.4,12.1,12.8,13.6,14.1,14.7,15.2,15.8,16.2,16.7,17.1,17.6],median:'15.0',insight:'Fitness Center 089 is below the staffing-efficiency band.'}},exceptions:[{store:'024',severity:'critical',title:'CO₂ above operating policy',meta:'1,260 ppm · peak occupancy',action:'Increase fresh air and verify recovery'},{store:'067',severity:'review',title:'HVAC running after close',meta:'46 min outside operating policy',action:'Verify schedule and occupancy state'},{store:'089',severity:'review',title:'Energy intensity above peer band',meta:'+15% per 100 visits',action:'Inspect HVAC and lighting runtime'}]}
  };
  let p=profiles[state.scenario];p.codes=commonCodes;return p;
}
function hqSpark(values){return `<span class="hq-spark">${values.map(v=>`<i style="height:${v}%"></i>`).join('')}</span>`}
function hq(){
  let p=hqProfile(),metricKey=state.hqMetric||'energy';if(!p.metrics[metricKey])metricKey='energy';let metric=p.metrics[metricKey],selected=state.hqStore||p.exceptions[0].store;if(!p.codes.includes(selected))selected=p.codes[0];
  let min=Math.min(...metric.values),max=Math.max(...metric.values),bars=p.codes.map((code,i)=>{let h=35+((metric.values[i]-min)/(max-min||1))*57,flag=i===0?'critical':i<3?'review':'normal';return `<button class="hq-bar-item ${selected===code?'selected':''} ${flag}" data-hq-store="${code}" aria-label="${esc(p.prefix)} ${code}: ${metric.values[i]} ${metric.unit}"><span class="hq-bar-value">${metric.values[i]}${metric.unit==='%'?'%':''}</span><i style="height:${h}%"></i><b>${code}</b></button>`}).join('');
  let selectedException=p.exceptions.find(x=>x.store===selected),selectedValue=metric.values[p.codes.indexOf(selected)],storeCards=['024','067','089','041'].map(code=>{let ex=p.exceptions.find(x=>x.store===code),idx=p.codes.indexOf(code),trend=[42+idx,58-idx,51+idx,66-idx,61+idx,72-idx];return `<button class="hq-store-card ${selected===code?'selected':''}" data-hq-store="${code}"><span class="hq-store-state ${ex?ex.severity:'normal'}"></span><div><small>${esc(p.prefix.toUpperCase())}</small><b>${code}</b><p>${ex?ex.title:'Operating within policy'}</p></div>${hqSpark(trend)}<em>${metric.values[idx]}${metric.unit==='%'?'%':metric.unit?' '+metric.unit:''}</em></button>`}).join('');
  return `<div class="page-title hq-title"><div><span class="eyebrow">02 · HQ COORDINATION</span><h1>Manage 100 ${esc(p.plural)} by exception—not store by store.</h1><p>Set one operating policy, compare like-for-like locations and direct local teams to the exceptions that matter.</p></div><div class="hq-format-switch">${Object.entries(DATA.scenarios).map(([id,s])=>`<button class="${state.scenario===id?'selected':''}" data-scenario="${id}">${esc(s.label.replace(/ [ABC]$/,''))}</button>`).join('')}</div></div><section class="hq-control-tower"><div class="hq-kpi-grid"><div><div><small>LOCATIONS REPORTING</small><strong>98 <span>/ 100</span></strong><p>2 connectivity checks</p></div>${hqSpark([52,58,63,67,72,78,84])}</div><div><div><small>POLICY COMPLIANCE</small><strong>91%</strong><p>+3 pts this period</p></div>${hqSpark([48,53,57,64,68,74,82])}</div><div class="attention"><div><small>OPEN EXCEPTIONS</small><strong>08</strong><p>2 immediate · 6 review</p></div>${hqSpark([82,74,69,61,55,47,38])}</div><div><div><small>TOP ENERGY VARIANCE</small><strong>+18%</strong><p>${esc(p.basis)} · Store 024</p></div>${hqSpark([34,41,48,54,59,72,88])}</div></div><div class="hq-command-grid"><section class="panel hq-benchmark"><div class="hq-panel-head"><div><span class="eyebrow">NORMALIZED CHAIN COMPARISON</span><h2>${esc(metric.title)} across 100 comparable locations</h2><p>${esc(p.basis)} · current operating period</p></div><div class="hq-metric-tabs">${[['energy','Energy'],['environment','Environment'],['traffic','Traffic']].map(x=>`<button class="${metricKey===x[0]?'selected':''}" data-hq-metric="${x[0]}">${x[1]}</button>`).join('')}</div></div><div class="hq-chart"><div class="hq-peer-band"><span>PEER OPERATING BAND</span></div><div class="hq-bars">${bars}</div></div><div class="hq-chart-summary"><div><small>CHAIN MEDIAN</small><b>${esc(metric.median)} ${esc(metric.unit)}</b></div><div><small>SELECTED LOCATION</small><b>${esc(p.prefix)} ${selected} · ${selectedValue}${metric.unit==='%'?'%':metric.unit?' '+metric.unit:''}</b></div><p>${esc(metric.insight)}</p></div></section><section class="panel hq-exceptions"><div class="hq-panel-head"><div><span class="eyebrow">EXCEPTION PRIORITY</span><h2>Act on what changed.</h2></div><span class="hq-count">08 OPEN</span></div><div class="hq-exception-list">${p.exceptions.map((x,i)=>`<button class="${selected===x.store?'selected':''}" data-hq-store="${x.store}"><span class="hq-severity ${x.severity}">0${i+1}</span><div><small>${esc(p.prefix)} ${x.store}</small><b>${esc(x.title)}</b><p>${esc(x.meta)}</p></div><i>→</i></button>`).join('')}</div><div class="hq-action-card"><small>${selectedException?'RECOMMENDED LOCAL ACTION':'SELECTED LOCATION'}</small><b>${selectedException?esc(selectedException.action):'No open exception'}</b><p>${selectedException?'HQ assigns the operating intent; the local team resolves and verifies the exception.':'Continue monitoring against the shared policy.'}</p><span>${selectedException?'ASSIGN → VERIFY → CLOSE':'WITHIN POLICY'}</span></div></section></div><div class="hq-store-strip">${storeCards}<div class="hq-more-stores"><strong>+96</strong><span>more locations monitored with the same policy</span></div></div><div class="hq-loop"><div><small>01</small><b>HQ POLICY</b><span>Set one standard</span></div><i>→</i><div><small>02</small><b>STORE EXECUTION</b><span>Operate locally</span></div><i>→</i><div><small>03</small><b>EXCEPTION ALERT</b><span>Surface variance</span></div><i>→</i><div><small>04</small><b>LOCAL ACTION</b><span>Resolve the cause</span></div><i>→</i><div><small>05</small><b>VERIFIED RESULT</b><span>Confirm recovery</span></div></div></section>`
}
function hvacEnergyDiagram(){return `<div class="hvac-day"><div class="hvac-day-heading"><div><small>ONE STORE · ONE OPERATING DAY</small><h3>One repeatable HVAC policy for every location.</h3></div><p>Reduce avoidable runtime while protecting comfort at opening and during traffic peaks.</p></div><div class="store-state-label">STORE STATE</div><div class="store-state-bar"><span class="closed" style="flex:22">CLOSED · SETBACK</span><span class="prepare" style="flex:10">PRE-OPEN</span><span class="open" style="flex:22">OPEN</span><span class="peak" style="flex:15">PEAK</span><span class="open" style="flex:19">OPEN</span><span class="closed" style="flex:12">CLOSED</span></div><div class="hvac-chart"><div class="hvac-output-label">HVAC OUTPUT</div><svg viewBox="0 0 760 225" role="img" aria-label="Retail store HVAC output across one operating day"><defs><pattern id="energyHatch" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(35)"><line x1="0" y1="0" x2="0" y2="8" stroke="#57c4e5" stroke-width="2" opacity=".45"/></pattern><linearGradient id="smartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#78d6ef" stop-opacity=".24"/><stop offset="1" stop-color="#78d6ef" stop-opacity=".04"/></linearGradient></defs><line class="chart-grid" x1="40" y1="55" x2="720" y2="55"/><line class="chart-grid" x1="40" y1="110" x2="720" y2="110"/><line class="chart-grid" x1="40" y1="165" x2="720" y2="165"/><path class="saved-area" d="M40 55H720V165H680C665 165 660 110 640 110H550C525 110 520 65 500 65H420C395 65 390 90 370 90H205C170 90 165 165 150 165H40Z"/><path class="smart-area" d="M40 165H150C165 165 170 90 205 90H370C390 90 395 65 420 65H500C520 65 525 110 550 110H640C660 110 665 165 680 165H720V190H40Z"/><path class="baseline-line" d="M40 55H720"/><path class="smart-line" d="M40 165H150C165 165 170 90 205 90H370C390 90 395 65 420 65H500C520 65 525 110 550 110H640C660 110 665 165 680 165H720"/><g class="chart-event"><circle cx="190" cy="104" r="6"/><text x="190" y="34" text-anchor="middle">PRE-CONDITION</text><line x1="190" y1="42" x2="190" y2="95"/></g><g class="chart-event"><circle cx="420" cy="65" r="6"/><text x="420" y="34" text-anchor="middle">OCCUPANCY RESPONSE</text><line x1="420" y1="42" x2="420" y2="56"/></g><g class="chart-event"><circle cx="680" cy="165" r="6"/><text x="680" y="34" text-anchor="middle">CLOSE VERIFIED</text><line x1="680" y1="42" x2="680" y2="156"/></g><text class="saved-label" x="340" y="132">AVOIDED HVAC RUNTIME</text><g class="x-axis"><text x="40" y="213">00:00</text><text x="205" y="213">06:00</text><text x="370" y="213">12:00</text><text x="550" y="213">18:00</text><text x="720" y="213" text-anchor="end">24:00</text></g></svg><div class="chart-legend"><span><i class="smart"></i>Smart operating policy</span><span><i class="baseline"></i>Continuous operation baseline</span><span><i class="saving"></i>Runtime avoided</span></div></div><div class="hvac-signal-flow"><div><small>SENSE</small><b>VS People Sensing<br>EM320-TH</b></div><i>→</i><div><small>CONTROL</small><b>UC722 · WT2x1<br>UC701 · WT30X</b></div><i>→</i><div><small>VERIFY</small><b>CT10X · CTH01<br>Zone conditions</b></div><i>→</i><div><small>COORDINATE</small><b>HQ policy<br>Local exceptions</b></div></div></div>`}
function closeRoutineDiagram(){let steps=[['20:55','CLOSE SIGNAL','Store schedule'],['21:00','SHUT DOWN','Approved loads'],['21:10','VERIFY','CT + device state'],['07:30','PRE-OPEN','Prepare key systems'],['08:00','READY','Comfort confirmed']];return `<div class="playbook-viz close-viz"><div class="viz-heading"><div><small>EVENING → OVERNIGHT → OPENING</small><h3>Close every store cleanly. Open every store ready.</h3></div><p>A shared schedule handles routine actions; local teams only receive exceptions.</p></div><div class="close-timeline">${steps.map((x,i)=>`<div class="close-step ${i===2?'verify':i===4?'ready':''}"><span>${x[0]}</span><i>${i===2?'✓':i===4?'●':'→'}</i><b>${x[1]}</b><small>${x[2]}</small></div>`).join('')}</div><div class="load-status-grid"><div><span class="load-icon">☼</span><small>LIGHTING</small><b>Off after close</b><p>WS51X / controller state</p><em>VERIFIED</em></div><div><span class="load-icon">❄</span><small>HVAC</small><b>Setback overnight</b><p>Controller + zone temperature</p><em>07:30 PRE-OPEN</em></div><div><span class="load-icon">ϟ</span><small>PLUG LOADS</small><b>Approved loads only</b><p>Smart socket + CT feedback</p><em>1 EXCEPTION</em></div></div><div class="viz-value-strip"><div><small>AFTER-HOURS CONTROL</small><b>Remove avoidable runtime</b></div><div><small>LOCAL ACCOUNTABILITY</small><b>Route only unresolved exceptions</b></div><div><small>OPENING EXPERIENCE</small><b>Confirm readiness before customers arrive</b></div></div></div>`}
function maintenanceDiagram(){return `<div class="playbook-viz maintenance-viz"><div class="viz-heading"><div><small>MULTI-SIGNAL EQUIPMENT HEALTH</small><h3>Find the fault pattern before the equipment stops.</h3></div><p>Current, temperature and leakage signals provide context for a targeted inspection.</p></div><div class="signal-card-grid"><div class="signal-card alert"><div><small>COMPRESSOR CURRENT</small><strong>13.8 A</strong><span>Baseline 10–12 A</span></div><svg viewBox="0 0 210 72"><path d="M4 52L25 50L45 53L65 49L85 50L105 47L125 50L145 22L165 18L185 24L206 20"/><line x1="4" y1="40" x2="206" y2="40"/></svg><em>ABOVE BASELINE</em></div><div class="signal-card"><div><small>SUPPLY / RETURN ΔT</small><strong>8.4°C</strong><span>Expected band selected by asset</span></div><svg viewBox="0 0 210 72"><path d="M4 30L25 31L45 29L65 32L85 31L105 35L125 37L145 41L165 43L185 46L206 47"/><line x1="4" y1="38" x2="206" y2="38"/></svg><em>TRENDING DOWN</em></div><div class="signal-card ok"><div><small>LEAK DETECTION</small><strong>DRY</strong><span>Kitchen / plant area</span></div><div class="leak-pulse"><i></i><span>No active event</span></div><em>NORMAL</em></div></div><div class="diagnostic-flow"><div><span>01</span><small>DETECT</small><b>Current exceeds asset baseline</b></div><i>→</i><div><span>02</span><small>CORRELATE</small><b>Check ΔT, pressure and leakage</b></div><i>→</i><div><span>03</span><small>INSPECT</small><b>Filter, fan or compressor</b></div><i>→</i><div><span>04</span><small>VERIFY</small><b>Confirm restored baseline</b></div></div><div class="maintenance-outcome"><b>PRIORITIZED ACTION</b><p>Inspect airflow and filter condition before authorizing a compressor intervention.</p><span>CT10X · TS302 · pressure / leak input</span></div></div>`}
function benchmarkDiagram(){return `<div class="playbook-viz benchmark-viz"><div class="viz-heading"><div><small>CHAIN-WIDE ENERGY BENCHMARK</small><h3>Compare like-for-like stores. Investigate the outlier.</h3></div><p>Sub-load visibility explains whether the variance comes from HVAC, lighting or equipment.</p></div><div class="benchmark-kpis"><div><small>PEER MEDIAN</small><strong>346</strong><span>kWh / reference day</span></div><div><small>TOP VARIANCE</small><strong>+18%</strong><span>Store D vs peer band</span></div><div><small>WITHIN POLICY</small><strong>4 / 5</strong><span>comparable locations</span></div></div><div class="benchmark-chart"><svg viewBox="0 0 760 245" role="img" aria-label="Energy comparison across five stores"><g class="benchmark-grid"><line x1="60" y1="45" x2="730" y2="45"/><line x1="60" y1="100" x2="730" y2="100"/><line x1="60" y1="155" x2="730" y2="155"/><line x1="60" y1="210" x2="730" y2="210"/></g><rect class="peer-band" x="60" y="90" width="670" height="55" rx="6"/><g class="store-bars"><g transform="translate(100)"><rect class="hvac" x="0" y="105" width="55" height="105"/><rect class="light" x="0" y="75" width="55" height="30"/><rect class="equip" x="0" y="55" width="55" height="20"/><text x="27" y="233">A</text></g><g transform="translate(225)"><rect class="hvac" x="0" y="115" width="55" height="95"/><rect class="light" x="0" y="82" width="55" height="33"/><rect class="equip" x="0" y="62" width="55" height="20"/><text x="27" y="233">B</text></g><g transform="translate(350)"><rect class="hvac" x="0" y="110" width="55" height="100"/><rect class="light" x="0" y="78" width="55" height="32"/><rect class="equip" x="0" y="58" width="55" height="20"/><text x="27" y="233">C</text></g><g class="outlier" transform="translate(475)"><rect class="hvac" x="0" y="82" width="55" height="128"/><rect class="light" x="0" y="50" width="55" height="32"/><rect class="equip" x="0" y="28" width="55" height="22"/><text x="27" y="233">D</text><text class="variance" x="27" y="18">+18%</text></g><g transform="translate(600)"><rect class="hvac" x="0" y="120" width="55" height="90"/><rect class="light" x="0" y="88" width="55" height="32"/><rect class="equip" x="0" y="65" width="55" height="23"/><text x="27" y="233">E</text></g></g></svg><div class="benchmark-legend"><span><i class="hvac"></i>HVAC</span><span><i class="light"></i>Lighting</span><span><i class="equip"></i>Equipment</span><span><i class="band"></i>Peer band</span></div></div><div class="benchmark-flow"><span>CT / CTH / WS51X</span><i>→</i><span>Normalize comparable stores</span><i>→</i><b>Investigate Store D HVAC</b><i>→</i><span>Verify correction</span></div></div>`}
function iaqDiagram(){return `<div class="playbook-viz iaq-viz"><div class="viz-heading"><div><small>OCCUPANCY · CO₂ · VENTILATION</small><h3>Increase fresh air when needed—not all day.</h3></div><p>Use occupancy and air-quality context to recover IAQ while watching HVAC demand.</p></div><div class="iaq-state-bar"><span>LOW TRAFFIC</span><span>BUILDING</span><span class="peak">PEAK OCCUPANCY</span><span>RECOVERY</span></div><div class="iaq-chart"><svg viewBox="0 0 760 250" role="img" aria-label="Occupancy, carbon dioxide and ventilation response"><defs><linearGradient id="occFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#235fa5" stop-opacity=".28"/><stop offset="1" stop-color="#235fa5" stop-opacity=".03"/></linearGradient></defs><g class="iaq-grid"><line x1="45" y1="45" x2="720" y2="45"/><line x1="45" y1="100" x2="720" y2="100"/><line x1="45" y1="155" x2="720" y2="155"/><line x1="45" y1="210" x2="720" y2="210"/></g><line class="co2-threshold" x1="45" y1="92" x2="720" y2="92"/><text class="threshold-label" x="715" y="84" text-anchor="end">CO₂ POLICY</text><path class="occupancy-area" d="M45 200C100 195 120 170 160 160S240 120 290 105S385 55 440 60S525 92 565 125S650 175 720 190V210H45Z"/><path class="co2-line" d="M45 178C105 176 130 160 170 148S250 116 300 95S385 62 440 70S520 88 555 112S640 150 720 166"/><path class="vent-line" d="M45 190H230C260 190 270 142 300 142H350C380 142 388 70 420 70H520C550 70 560 132 590 132H650C675 132 685 180 720 180"/><g class="iaq-event"><circle cx="300" cy="142" r="6"/><text x="300" y="128" text-anchor="middle">VENTILATION UP</text><circle cx="590" cy="132" r="6"/><text x="590" y="118" text-anchor="middle">RECOVERY</text></g><g class="iaq-axis"><text x="45" y="235">08:00</text><text x="270" y="235">12:00</text><text x="500" y="235">16:00</text><text x="720" y="235" text-anchor="end">20:00</text></g></svg><div class="iaq-legend"><span><i class="occ"></i>Occupancy</span><span><i class="co2"></i>CO₂</span><span><i class="vent"></i>Ventilation command</span></div></div><div class="iaq-response-grid"><div><small>OBSERVE</small><b>VS occupancy + AM Series CO₂</b></div><div><small>DECIDE</small><b>Apply approved IAQ policy</b></div><div><small>ACT</small><b>Increase fresh air / HVAC mode</b></div><div><small>VERIFY</small><b>CO₂ recovery + energy response</b></div></div></div>`}
function trafficAnalyticsDiagram(){return `<div class="playbook-viz traffic-viz"><div class="viz-heading"><div><small>RETAIL TRAFFIC · FROM COUNTS TO DECISIONS</small><h3>See where customers go—and what the store should do next.</h3></div><p>One retail view connects staffing, merchandising, campaigns, chain comparison and demand-led energy control.</p></div><div class="traffic-value-grid"><div><span>01</span><b>Staff to demand</b><small>Match shifts to peaks and valleys.</small></div><div><span>02</span><b>Improve the floor</b><small>Refine layout, counters and windows.</small></div><div><span>03</span><b>Measure campaigns</b><small>Compare attraction and entry conversion.</small></div><div><span>04</span><b>Compare stores</b><small>Find low-performing locations.</small></div><div><span>05</span><b>Control on demand</b><small>Link HVAC and lighting to occupancy.</small></div></div><div class="traffic-kpi-grid"><div><small>LIVE OCCUPANCY</small><strong>186</strong><span>0.14 person / m²</span></div><div><small>ENTRY CONVERSION</small><strong>31.6%</strong><span>898 entries / 2,840 passers-by</span></div><div><small>AVERAGE DWELL</small><strong>18.4 min</strong><span>+2.1 min vs last week</span></div><div><small>PEAK / VALLEY</small><strong>17:00 / 10:00</strong><span>146 / 22 entries per hour</span></div></div><div class="traffic-analysis-grid"><section class="traffic-tide"><div class="traffic-card-head"><div><small>HOURLY STORE TRAFFIC</small><b>Today vs previous period</b></div><span>WoW +8.2% · MoM +5.6%</span></div><svg viewBox="0 0 470 205" role="img" aria-label="Retail hourly traffic trend"><defs><linearGradient id="trafficFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#00a7d5" stop-opacity=".28"/><stop offset="1" stop-color="#00a7d5" stop-opacity=".03"/></linearGradient></defs><g class="traffic-grid-lines"><line x1="35" y1="35" x2="450" y2="35"/><line x1="35" y1="85" x2="450" y2="85"/><line x1="35" y1="135" x2="450" y2="135"/><line x1="35" y1="175" x2="450" y2="175"/></g><path class="traffic-previous" d="M35 159L75 145L115 152L155 120L195 105L235 112L275 82L315 70L355 93L395 120L450 148"/><path class="traffic-area" d="M35 165L75 154L115 160L155 128L195 98L235 105L275 72L315 40L355 78L395 108L450 140V175H35Z"/><path class="traffic-today" d="M35 165L75 154L115 160L155 128L195 98L235 105L275 72L315 40L355 78L395 108L450 140"/><g class="traffic-event"><circle cx="315" cy="40" r="5"/><text x="315" y="25" text-anchor="middle">PEAK · ADD COVERAGE</text><circle cx="115" cy="160" r="5"/><text x="115" y="148" text-anchor="middle">VALLEY</text></g><g class="traffic-axis"><text x="35" y="196">09:00</text><text x="155" y="196">12:00</text><text x="275" y="196">15:00</text><text x="395" y="196">18:00</text><text x="450" y="196" text-anchor="end">20:00</text></g></svg><div class="traffic-legend"><span><i class="today"></i>Today entries</span><span><i class="previous"></i>Previous period</span><b>Staffing action: add 2 associates at 16:30</b></div></section><section class="traffic-floor"><div class="traffic-card-head"><div><small>ZONE SHARE & VISITOR PATHS</small><b>Retail Store A</b></div><span>Selected day</span></div><svg viewBox="0 0 330 205" role="img" aria-label="Retail store zone traffic and visitor movement"><defs><radialGradient id="retailHeatHot"><stop offset="0" stop-color="#f09a42" stop-opacity=".72"/><stop offset="1" stop-color="#f09a42" stop-opacity="0"/></radialGradient><radialGradient id="retailHeatCool"><stop offset="0" stop-color="#00a7d5" stop-opacity=".55"/><stop offset="1" stop-color="#00a7d5" stop-opacity="0"/></radialGradient><marker id="flowArrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L0,6 L7,3 z" fill="#235fa5"/></marker></defs><rect class="floor-shell" x="12" y="12" width="306" height="174" rx="9"/><rect class="zone-zone" x="24" y="24" width="78" height="68" rx="6"/><rect class="zone-zone" x="112" y="24" width="194" height="68" rx="6"/><rect class="zone-zone" x="24" y="102" width="176" height="72" rx="6"/><rect class="zone-zone" x="210" y="102" width="96" height="72" rx="6"/><circle cx="62" cy="122" r="49" fill="url(#retailHeatCool)"/><circle cx="205" cy="66" r="65" fill="url(#retailHeatHot)"/><circle cx="260" cy="138" r="42" fill="url(#retailHeatCool)"/><g class="zone-label"><text x="63" y="48" text-anchor="middle">ENTRANCE</text><text x="63" y="64" text-anchor="middle">27%</text><text x="208" y="48" text-anchor="middle">CORE DISPLAY</text><text x="208" y="64" text-anchor="middle">36%</text><text x="112" y="130" text-anchor="middle">ESSENTIALS</text><text x="112" y="146" text-anchor="middle">21%</text><text x="258" y="130" text-anchor="middle">CHECKOUT</text><text x="258" y="146" text-anchor="middle">16%</text></g><g class="visitor-flow"><path d="M18 108C48 92 70 82 104 67"/><path d="M104 67C140 61 160 62 178 65"/><path d="M220 79C245 93 255 105 260 116"/><path class="secondary" d="M91 93C95 112 99 118 104 123"/></g></svg><div class="path-insight"><b>TOP PATH · 42%</b><span>Entrance → Core display → Checkout</span><em>Layout action: strengthen the Essentials transition.</em></div></section></div></div>`}
function optimize(){let scenarioPlaybook={retail:'traffic',restaurant:'cold',fitness:'iaq'}[state.scenario],ids=['close','occupancy','maintenance','benchmark',scenarioPlaybook],available=DATA.automation.filter(x=>ids.includes(x.id));if(!ids.includes(state.automation))state.automation=scenarioPlaybook;let a=DATA.automation.find(x=>x.id===state.automation),visuals={close:closeRoutineDiagram,occupancy:hvacEnergyDiagram,maintenance:maintenanceDiagram,benchmark:benchmarkDiagram,iaq:iaqDiagram,cold:coldChainDiagram,traffic:trafficAnalyticsDiagram},visual=visuals[a.id],detail=visual?visual():`<p class="lead">${a.summary}</p><div class="workflow-steps">${[['OBSERVE',a.observe],['DECIDE',a.decide],['ACT',a.act],['VERIFY',a.verify]].map((x,i)=>`<div><span>0${i+1}</span><small>${x[0]}</small><p>${x[1]}</p></div>`).join('')}</div>`;return `<div class="page-title"><div><span class="eyebrow">03 · DATA-TO-ACTION LOOP</span><h1>Turn connected data into repeatable operations.</h1><p>Four shared operating loops plus one playbook for the selected business format.</p></div><div class="loop-badge">${esc(scenario().label)} · OBSERVE → DECIDE → ACT → VERIFY</div></div><div class="optimize-layout"><div class="automation-list">${available.map((x,i)=>`<button class="${state.automation===x.id?'selected':''}" data-automation="${x.id}"><span>0${i+1}</span><div><b>${x.title}</b><p>${x.summary}</p></div><i>→</i></button>`).join('')}</div><section class="panel automation-detail ${visual?'visual-playbook-panel':''}"><div class="section-head"><div><span class="eyebrow">SELECTED OPERATING PLAYBOOK</span><h2>${a.title}</h2></div><span class="status ok">REPEATABLE</span></div>${detail}</section></div>`}
function architecture(){
  const layers=[['1 · SENSE & CONTROL',['People sensing','HVAC','Energy','Facility','IAQ / Cold chain']],['2 · CONNECT',['LoRaWAN sensors','Gateway','Cellular transport']],['3 · INTEGRATE',['Network server','Application platform','API / BMS']],['4 · OPERATE',['Monitor','Alert','Control','Verify']]];
  const layerHtml=layers.map((x,i)=>`<div class="arch-layer ${i===1?'emphasis':i===3?'dark':''}"><small>${x[0]}</small><div>${x[1].map(y=>`<span>${y}</span>`).join('')}</div></div>${i<3?'<i>↓</i>':''}`).join('');
  const reasons=[['Wireless retrofit','Reduce cabling and business disruption, subject to site conditions.'],['Low-power endpoints','Battery life varies by model, reporting and radio conditions.'],['Broad store coverage','One gateway may cover a site; radio validation is still required.'],['Open ecosystem','LoRaWAN supports multi-vendor integration; interfaces need definition.']];
  return `<div class="architecture">${layerHtml}</div><div class="why-grid">${reasons.map((x,i)=>`<div><span>0${i+1}</span><b>${x[0]}</b><p>${x[1]}</p></div>`).join('')}</div>`;
}
function mapping(id){return state.mappings[id]||DATA.modules[id].products.map(p=>DATA.products[p].model).join(' + ')}
function bomRows(){let r=state.enabled.filter(id=>DATA.modules[id]).map(id=>({id,name:DATA.modules[id].name,map:mapping(id)}));if(r.length)r.push({id:'gateway',name:'Connectivity',map:state.mappings.gateway||'UG65 / Gateway — To confirm'});return r}
function bom(){let rows=bomRows(),sub=0,missing=0;rows.forEach(r=>{let p=state.prices[r.id];p===null||p===''||p===undefined?missing++:sub+=(+p||0)*(+state.quantities[r.id]||0)});return `<div class="builder"><aside><label><span>Business format</span><select id="builder-scenario">${Object.entries(DATA.scenarios).map(([id,s])=>`<option value="${id}" ${state.scenario===id?'selected':''}>${s.label}</option>`).join('')}</select></label><label><span>Locations in rollout</span><input id="store-count" type="number" min="1" value="${state.stores}"></label><div class="module-checks">${Object.entries(DATA.modules).map(([id,m])=>`<label><input type="checkbox" data-enable="${id}" ${state.enabled.includes(id)?'checked':''}><span><b>${m.name}</b><small>${scenario().modules.includes(id)?'Recommended':'Optional'}</small></span></label>`).join('')}</div></aside><section><div class="section-head"><div><span class="eyebrow">PRELIMINARY BILL OF MATERIALS</span><h2>Scope first. Validate before quotation.</h2></div><button class="primary" id="csv">Export CSV ↓</button></div><div class="notice">Mappings, quantities and USD prices are editable planning fields—not a confirmed design or quotation.</div><table class="bom-table"><thead><tr><th>MODULE / CANDIDATE MAPPING</th><th>QTY / SITE</th><th>UNIT USD</th><th>ROLLOUT QTY</th><th>STATUS</th></tr></thead><tbody>${rows.map(r=>{let incomplete=state.prices[r.id]===null||state.prices[r.id]===undefined||state.prices[r.id]==='';return `<tr><td><b>${r.name}</b><input data-map="${r.id}" value="${esc(r.map)}"></td><td><input data-qty="${r.id}" type="number" min="0" value="${state.quantities[r.id]||0}"></td><td><input data-price="${r.id}" type="number" min="0" placeholder="TBC" value="${state.prices[r.id]??''}"></td><td>${money((state.quantities[r.id]||0)*state.stores)}</td><td><span class="status ${incomplete?'warn':'ok'}">${incomplete?'INCOMPLETE':'PRICED'}</span></td></tr>`}).join('')}</tbody></table><div class="builder-total"><div><small>PRICED HARDWARE / SITE</small><strong>$${money(sub)}</strong></div><div><small>PRICED HARDWARE / ROLLOUT</small><strong>$${money(sub*state.stores)}</strong></div><p>${missing} unpriced rows · Installation, platform, services, freight and tax excluded.</p></div></section></div>`}
function checklist(){return `<div class="checklist-layout"><section class="panel"><span class="eyebrow">PILOT READINESS CHECKLIST</span><h2>Validate the repeatable unit before scaling.</h2><p class="lead">Prove compatibility, coverage, response and acceptance criteria—not only data delivery.</p><div class="pilot-list">${DATA.pilotChecklist.map((x,i)=>`<label><input type="checkbox"><span><small>0${i+1}</small><b>${x}</b></span></label>`).join('')}</div></section><section class="panel pilot-path"><span class="eyebrow">PILOT-TO-ROLLOUT</span><h2>One approved site becomes the chain standard.</h2>${[['DISCOVER','Survey equipment and intent'],['PILOT','Install and validate response'],['APPROVE','Freeze mappings and evidence'],['REPLICATE','Deploy with repeatable support']].map((x,i)=>`<div><span>0${i+1}</span><b>${x[0]}</b><p>${x[1]}</p></div>`).join('')}</section></div>`}
function deploy(){return `<div class="page-title"><div><span class="eyebrow">04 · SCALABLE DEPLOYMENT</span><h1>Build a solution that can repeat across every location.</h1><p>Connect architecture, BOM and pilot acceptance before rollout.</p></div><div class="deploy-tabs">${[['architecture','Why LoRaWAN'],['bom','Build the rollout'],['pilot','Pilot readiness']].map(x=>`<button class="${state.deployTab===x[0]?'selected':''}" data-deploy="${x[0]}">${x[1]}</button>`).join('')}</div></div><section class="panel deploy-body">${state.deployTab==='architecture'?architecture():state.deployTab==='bom'?bom():checklist()}</section>`}
function roiVals(){let r=state.roi,g=+r.energySaving + +r.maintenanceSaving + +r.labor,n=g-+r.service;return{g,n,p:n>0?+r.capex/n*12:0,roi:(n*3-+r.capex)/+r.capex*100}}
function prove(){
  const products=[
    ['CT101','HVAC circuit monitoring','Installed inside the electrical panel to establish the HVAC energy baseline.','assets/case-study/ct101-official-install.png','https://www.milesight.com/iot/product/lorawan-sensor/ct10x'],
    ['AM103','Indoor air quality','Wall-mounted in the store to track CO₂, temperature and humidity.','assets/case-study/am103-scene.png','https://www.milesight.com/iot/product/lorawan-sensor/am103-am103l','assets/case-study/am103-product-crop.png','left'],
    ['EM320-TH','Remote zone sensing','Wall-mounted zone sensor supplying temperature and humidity context.','assets/case-study/em320-th-scene.png','https://www.milesight.com/iot/product/lorawan-sensor/em320-th','assets/case-study/em320-product-3.png','right'],
    ['WT211','RTU control','Wall thermostat applying schedules, setpoints and D2D responses.','assets/case-study/wt211-application.jpg','https://www.milesight.com/iot/product/lorawan-sensor/wt201'],
    ['UG56','LoRaWAN connectivity','Industrial gateway connecting site devices to the operations platform.','assets/case-study/ug56-product.png','https://www.milesight.com/iot/product/lorawan-gateway/ug56']
  ];
  return `<div class="page-title case-study-title"><div><span class="eyebrow">05 · CASE STUDY</span><h1>Chain Gas Station Convenience Store Project</h1><p>Centralized HVAC visibility and control across 250 locations, with per-store investment and return clearly quantified.</p></div><span class="case-study-badge">250 LOCATIONS</span></div><div class="prove-layout case-study-layout"><section class="panel case-card case-study-products"><div class="case-study-head"><div><span>PROJECT SOLUTION</span><h2>From circuit-level visibility to coordinated HVAC control.</h2></div><p>Official Milesight product appearance is preserved in every installation view.</p></div><div class="case-device-grid">${products.map((p,i)=>`<a class="case-device" href="${p[4]}" target="_blank" rel="noreferrer"><div class="case-device-image ${p[5]?'has-official-device':''} ${p[6]||''}"><img class="case-scene" src="${p[3]}" alt="${p[0]} installation or application">${p[5]?`<span class="official-device"><img src="${p[5]}" alt="Official ${p[0]} product appearance"></span>`:''}</div><div class="case-device-copy"><small>0${i+1}</small><strong>${p[0]}</strong><b>${p[1]}</b><p>${p[2]}</p><span>Official product page ↗</span></div></a>`).join('')}</div><div class="case-solution-flow"><span>MEASURE</span><i>→</i><span>UNDERSTAND</span><i>→</i><span>CONTROL</span><i>→</i><span>VERIFY</span></div></section><section class="panel roi-card case-study-roi"><div class="section-head"><div><span class="eyebrow">PER-STORE ROI</span><h2>How the project pays back.</h2></div><span class="pill">USD / YEAR</span></div><div class="roi-baseline"><div><small>ANNUAL ELECTRICITY BILL</small><strong>$30,000</strong></div><i>×</i><div><small>HVAC SHARE</small><strong>40%</strong></div><i>=</i><div class="accent"><small>HVAC BASELINE</small><strong>$12,000</strong></div></div><div class="roi-saving-bridge"><div><small>HVAC ENERGY SAVING</small><strong>+$1,200</strong><span>10% of HVAC baseline</span></div><div><small>MAINTENANCE SAVING</small><strong>+$180</strong><span>avoided service cost</span></div><div class="minus"><small>ANNUAL SERVICE FEE</small><strong>−$240</strong><span>recurring platform service</span></div></div><div class="roi-results fixed"><div><small>INITIAL INVESTMENT</small><strong>$2,400</strong><span>hardware + installation</span></div><div><small>ANNUAL NET CASH SAVING</small><strong>$1,140</strong><span>$1,200 + $180 − $240</span></div><div><small>CASH PAYBACK</small><strong>25.3</strong><span>months</span></div><div><small>3-YEAR NET ROI</small><strong>42.5%</strong><span>($1,140 × 3 − $2,400) ÷ $2,400</span></div></div><div class="roi-how"><h3>How to read the ROI</h3><ol><li><b>Set the baseline.</b><span>The store spends $30,000 on electricity; 40% is HVAC, so the addressable HVAC cost is $12,000.</span></li><li><b>Calculate annual benefit.</b><span>A 10% HVAC reduction saves $1,200; maintenance savings add $180.</span></li><li><b>Subtract recurring cost.</b><span>After the $240 annual service fee, the store keeps $1,140 in net cash savings each year.</span></li><li><b>Compare benefit with investment.</b><span>A $2,400 initial investment pays back in 25.3 months and generates $1,020 net value over three years.</span></li></ol></div><div class="roi-uplift"><div><small>WITH $240 ANNUAL LABOR VALUE</small><strong>$1,380</strong><span>annual total benefit</span></div><div><small>PAYBACK IMPROVES TO</small><strong>20.9 months</strong><span>$2,400 ÷ $1,380 × 12</span></div></div></section></div>`
}
const originalCloseRoutineDiagram=closeRoutineDiagram,originalHvacEnergyDiagram=hvacEnergyDiagram,originalMaintenanceDiagram=maintenanceDiagram,originalBenchmarkDiagram=benchmarkDiagram,originalIaqDiagram=iaqDiagram;
closeRoutineDiagram=()=>originalCloseRoutineDiagram().replace('WS51X / controller state','WS558 / lighting state').replace('Smart socket + CT feedback','WS51X + CT feedback');
hvacEnergyDiagram=()=>originalHvacEnergyDiagram().replace('Retail store HVAC output','Store HVAC output').replace('WT2x1','WT201 / WT211').replace('CT10X · CTH01','CT1 / CT3 · CTH01');
maintenanceDiagram=()=>originalMaintenanceDiagram().replace('Check ΔT, pressure and leakage','Check ΔT, leakage and optional pressure').replace('CT10X · TS302 · pressure / leak input','CT1 / CT3 · TS302 · leak input · pressure coming soon');
benchmarkDiagram=()=>originalBenchmarkDiagram().replace('Compare like-for-like stores. Investigate the outlier.','Compare 100 like-for-like locations. Investigate the outlier.').replace('Energy comparison across five stores','Representative comparison across a 100-location network').replace('<strong>346</strong>','<strong>36.8</strong>').replace('kWh / reference day','kWh / 100 visits').replace('Store D vs peer band','Store 024 vs peer median').replace('<strong>4 / 5</strong>','<strong>91 / 100</strong>').replace('comparable locations','locations within policy').replace('>A</text>','>012</text>').replace('>B</text>','>041</text>').replace('>C</text>','>067</text>').replace('>D</text>','>024</text>').replace('>E</text>','>100</text>').replace('CT / CTH / WS51X','CT / CTH / WS51X / WS558').replace('Investigate Store D HVAC','Investigate Store 024 HVAC');
iaqDiagram=()=>originalIaqDiagram().replace('VS occupancy + AM Series CO₂','VS occupancy + AM103 / AM300').replace('Increase fresh air / HVAC mode','Controller / BAS adjusts fresh air');
function coldChainDiagram(){return `<div class="playbook-viz maintenance-viz"><div class="viz-heading"><div><small>TEMPERATURE · DOOR · LOCATION</small><h3>Find the cold-chain exception, protect the product and retain the record.</h3></div><p>One response flow connects static storage, display cabinets and in-transit monitoring.</p></div><div class="signal-card-grid"><div class="signal-card ok"><div><small>COLD ROOM</small><strong>3.2°C</strong><span>EM300-TH / EM320-TH</span></div><svg viewBox="0 0 210 72"><path d="M4 42L28 40L52 41L76 39L100 41L124 40L148 42L172 41L206 40"/><line x1="4" y1="50" x2="206" y2="50"/></svg><em>WITHIN POLICY</em></div><div class="signal-card alert"><div><small>DISPLAY CABINET</small><strong>6.8°C</strong><span>Door open · 7 min</span></div><svg viewBox="0 0 210 72"><path d="M4 52L28 51L52 50L76 47L100 42L124 34L148 26L172 20L206 18"/><line x1="4" y1="40" x2="206" y2="40"/></svg><em>LOCAL ACTION</em></div><div class="signal-card ok"><div><small>IN-TRANSIT</small><strong>4.1°C</strong><span>TS60X · Route 08</span></div><svg viewBox="0 0 210 72"><path d="M4 43L28 42L52 44L76 41L100 42L124 40L148 41L172 39L206 41"/><line x1="4" y1="50" x2="206" y2="50"/></svg><em>NORMAL</em></div></div><div class="diagnostic-flow"><div><span>01</span><small>OBSERVE</small><b>Temperature, door and location events</b></div><i>→</i><div><span>02</span><small>DECIDE</small><b>Identify the affected cold-chain stage</b></div><i>→</i><div><span>03</span><small>ACT</small><b>Inspect door and protect exposed product</b></div><i>→</i><div><span>04</span><small>VERIFY</small><b>Confirm recovery and retain history</b></div></div><div class="maintenance-outcome"><b>PRIORITIZED ACTION</b><p>Inspect the display-cabinet door and review seven minutes of product exposure.</p><span>EM300 / EM320 · TS201 / TS30X · TS60X</span></div></div>`}
trafficAnalyticsDiagram=()=>`<div class="traffic-business-values" aria-label="Business value of retail traffic analytics"><div><span>01</span><b>Match staffing to traffic</b></div><div><span>02</span><b>Optimize layout, counters & window displays</b></div><div><span>03</span><b>Measure campaign traffic impact</b></div><div><span>04</span><b>Benchmark stores & identify low performers</b></div><div><span>05</span><b>Link HVAC & lighting to demand</b></div></div><div class="traffic-dashboard-frame"><iframe src="traffic-dashboard.html" title="Retail traffic analytics dashboard" loading="eager" allowfullscreen></iframe></div>`;

const GATEWAY_OPTIONS={
  ug63:{model:'UG63',fit:'Small locations',name:'Mini LoRaWAN Gateway',image:'https://www.milesight.com/static/pc/en/nav/new/iot-products/lorawan-gateways/mini-lorawan-gateway-ug63-illus.svg',features:['COMPACT','SMALL SITE','4G · ETHERNET'],url:'https://www.milesight.com/iot/product/lorawan-gateway/ug63'},
  ug56:{model:'UG56',fit:'Medium locations',name:'Industrial LoRaWAN Gateway',image:'https://www.milesight.com/static/pc/en/nav/new/iot-products/lorawan-gateways/industrial-lorawan-gateway-ug56-illus.svg',features:['INDUSTRIAL','PYTHON SDK','NODE-RED'],url:'https://www.milesight.com/iot/product/lorawan-gateway/ug56'},
  ug65:{model:'UG65',fit:'Large locations',name:'Indoor LoRaWAN Gateway',image:'https://www.milesight.com/static/pc/en/nav/new/iot-products/lorawan-gateways/indoor-lorawan-gateway-ug65-illus.svg',features:['HIGH CAPACITY','PYTHON SDK','NODE-RED'],url:'https://www.milesight.com/iot/product/lorawan-gateway/ug65'},
  eg71:{model:'EG71',fit:'Edge control',name:'Building IoT Gateway',image:'https://www.milesight.com/static/pc/en/nav/new/iot-products/lorawan-gateways/eg71-building-iot-gateway.svg',features:['EDGE CONTROL','MULTI-PROTOCOL','PYTHON SDK','NODE-RED'],url:'https://www.milesight.com/iot/product/lorawan-gateway/eg71'}
};

architecture=()=>{
  let selected=GATEWAY_OPTIONS[state.gateway]||GATEWAY_OPTIONS.ug63;
  let moduleNodes=scenario().modules.map(id=>`<span><i>${DATA.modules[id].icon}</i>${DATA.modules[id].name}</span>`).join('');
  let directPath=state.scenario==='restaurant'?'<p class="topology-direct-note">TS60X uses cellular connectivity and can report directly to the platform.</p>':'';
  let gatewayPicker=`<div class="gateway-picker"><div class="gateway-picker-head"><div><span class="eyebrow">GATEWAY OPTIONS</span><b>Choose the access layer for each site type.</b></div><p>Coverage, backhaul and integration are confirmed during site design.</p></div><div class="gateway-option-grid">${Object.entries(GATEWAY_OPTIONS).map(([id,g])=>`<button class="gateway-option ${state.gateway===id?'selected':''}" data-gateway="${id}"><div class="gateway-option-image"><img src="${g.image}" alt="${g.model}"></div><div class="gateway-option-copy"><span>${g.fit}</span><strong>${g.model}</strong><b>${g.name}</b><div class="gateway-keywords">${g.features.map(x=>`<em>${x}</em>`).join('')}</div><a href="${g.url}" target="_blank" rel="noreferrer" aria-label="Open ${g.model} product page">View product ↗</a></div></button>`).join('')}</div></div>`;
  return `<div class="solution-topology"><div class="topology-head"><span class="eyebrow">END-TO-END SOLUTION TOPOLOGY</span><span class="topology-scenario">${esc(scenario().label)}</span></div><div class="topology-flow"><section class="topology-node device-node"><small><i>01</i> SENSORS & CONTROLLERS</small><h3>Observe and act at the location</h3><div class="topology-module-list">${moduleNodes}</div>${directPath}</section><i>→</i><section class="topology-node gateway-node"><small><i>02</i> GATEWAY</small><img class="gateway-selected-image" src="${selected.image}" alt="${selected.model}"><strong>${selected.model}</strong><b>${selected.fit}</b><p>${selected.name}</p></section><i>→</i><section class="topology-node route-node"><small><i>03</i> CHOOSE A PATH</small><div class="route-choice direct"><span>DIRECT</span><b>MQTT / HTTP(S)</b><p>Gateway forwards data directly.</p></div><em>OR</em><div class="route-choice managed"><span>MANAGED</span><b>Milesight Development Platform</b><p>Centralized access and management first.</p></div></section><i>→</i><section class="topology-node customer-platform-node"><small><i>04</i> CUSTOMER PLATFORM</small><h3>Applications & integrations</h3><div><span>DASHBOARD</span><span>API</span><span>BMS</span><span>WORKFLOWS</span></div></section><i>→</i><section class="topology-node hq-node"><small><i>05</i> HQ OPERATIONS</small><h3>Coordinate every location</h3><div><span>MONITOR</span><span>ALERT</span><span>CONTROL</span><span>VERIFY</span></div></section></div>${gatewayPicker}</div>`;
};

bom=()=>{
  let modules=scenario().modules.map(id=>[id,DATA.modules[id]]);
  return `<div class="rollout-summary"><div class="rollout-head"><div><span class="eyebrow">SELECTED SOLUTION SUMMARY</span><h2>Bring the explored modules and products into one rollout view.</h2><p>The summary follows the selected business format; final model selection still depends on site conditions and compatibility.</p></div><span class="topology-scenario">${esc(scenario().label)}</span></div><div class="rollout-module-grid">${modules.map(([id,m],index)=>`<section class="rollout-module-card"><header><span>${String(index+1).padStart(2,'0')}</span><div><h3>${m.name}</h3><p>${m.action}</p></div></header><div class="rollout-products">${m.products.map(pid=>{let p=DATA.products[pid];return `<a href="${p.url}" target="_blank" rel="noreferrer" class="rollout-product"><div class="rollout-product-image">${p.image?`<img src="${p.image}" alt="">`:'<span>＋</span>'}</div><div><b>${p.model}</b><span>${p.name}</span></div><i>↗</i></a>`}).join('')}</div></section>`).join('')}</div><div class="rollout-connectivity"><span>CONNECTIVITY</span><b>Choose UG63, UG56, UG65 or EG71 in the topology view.</b><p>The gateway completes the shared access layer for the selected sensors and controllers.</p></div></div>`;
};

deploy=()=>`<div class="page-title"><div><span class="eyebrow">04 · SCALABLE DEPLOYMENT</span><h1>Connect every device. Repeat the solution.</h1></div><div class="deploy-tabs">${[['architecture','Solution topology'],['bom','Build the rollout'],['pilot','Pilot readiness']].map(x=>`<button class="${state.deployTab===x[0]?'selected':''}" data-deploy="${x[0]}">${x[1]}</button>`).join('')}</div></div><section class="panel deploy-body">${state.deployTab==='architecture'?architecture():state.deployTab==='bom'?bom():checklist()}</section>`;

const pages={explore,hq,optimize,deploy,prove};
function bind(){ $$('[data-scenario]').forEach(b=>b.onclick=()=>{state.scenario=b.dataset.scenario;state.enabled=[...scenario().modules];state.module=state.enabled[0];state.zone=0;render()});$$('[data-module]').forEach(b=>b.onclick=()=>{state.module=b.dataset.module;state.zone=0;render()});$$('[data-zone]').forEach(b=>b.onclick=()=>{state.zone=+b.dataset.zone;render()});$$('[data-automation]').forEach(b=>b.onclick=()=>{state.automation=b.dataset.automation;render()});$$('[data-deploy]').forEach(b=>b.onclick=()=>{state.deployTab=b.dataset.deploy;render()});
  $$('[data-gateway]').forEach(b=>b.onclick=e=>{if(e.target.closest('a'))return;e.preventDefault();state.gateway=b.dataset.gateway;render()});let gatewayToggle=$('[data-gateway-toggle]');if(gatewayToggle)gatewayToggle.onclick=()=>{state.gatewayOpen=!state.gatewayOpen;render()};
  $$('[data-hq-metric]').forEach(b=>b.onclick=()=>{state.hqMetric=b.dataset.hqMetric;render()});$$('[data-hq-store]').forEach(b=>b.onclick=()=>{state.hqStore=b.dataset.hqStore;render()});
  let s=$('#builder-scenario');if(s)s.onchange=()=>{state.scenario=s.value;state.enabled=[...scenario().modules];state.module=state.enabled[0];render()};let n=$('#store-count');if(n)n.onchange=()=>{state.stores=Math.max(1,+n.value||1);render()};$$('[data-enable]').forEach(e=>e.onchange=()=>{state.enabled=e.checked?[...new Set([...state.enabled,e.dataset.enable])]:state.enabled.filter(x=>x!==e.dataset.enable);render()});$$('[data-map]').forEach(e=>e.onchange=()=>{state.mappings[e.dataset.map]=e.value;persist()});$$('[data-qty]').forEach(e=>e.onchange=()=>{state.quantities[e.dataset.qty]=Math.max(0,+e.value||0);render()});$$('[data-price]').forEach(e=>e.onchange=()=>{state.prices[e.dataset.price]=e.value===''?null:+e.value;render()});$$('[data-roi]').forEach(e=>e.onchange=()=>{state.roi[e.dataset.roi]=Math.max(0,+e.value||0);render()});let c=$('#csv');if(c)c.onclick=exportCsv;
}
function exportCsv(){let q=x=>'"'+String(x??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"',rows=[['Milesight preliminary BOM'],['Format',scenario().label],['Locations',state.stores],['Module','Candidate mapping','Qty/site','Unit USD','Rollout qty','Status'],...bomRows().map(r=>[r.name,r.map,state.quantities[r.id],state.prices[r.id]??'',state.quantities[r.id]*state.stores,state.prices[r.id]==null?'Incomplete':'Planning assumption'])];download('milesight-multisite-preliminary-bom.csv','\uFEFF'+rows.map(r=>r.map(q).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function refineRoiStory(){
  if(state.page!=='prove')return;
  let heading=$('.roi-how h3'),items=$$('.roi-how li');
  if(heading)heading.textContent='What this means for your business';
  const story=[
    ['Lower operating costs, every year','Reduce HVAC energy use and maintenance expenses. Annual net saving after service fees is $1,140 per store.'],
    ['Recover the investment in 25.3 months','A $2,400 investment per store pays back in 25.3 months and produces a three-year net ROI of 42.5%.'],
    ['Spot issues before they disrupt the store','Connected monitoring helps teams identify abnormal equipment operation and respond earlier.'],
    ['Build confidence before scaling','Use measured store performance to validate the savings and guide rollout across the chain.']
  ];
  items.forEach((item,i)=>{if(!story[i])return;let title=item.querySelector('b'),copy=item.querySelector('span');if(title)title.textContent=story[i][0];if(copy)copy.textContent=story[i][1]});
}
function render(){if(window.coverOpen){renderCover();return}$('#app').dataset.page=state.page;$('#app').innerHTML=(pages[state.page]||explore)();refineRoiStory();$('#crumb').textContent={explore:'Explore the store',hq:'Connect the chain',optimize:'Optimize operations',deploy:'Deploy the solution',prove:'Case study'}[state.page];bind();persist();if(window.scheduleFit)scheduleFit()}
$('#fullscreen').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();
